from pathlib import Path
import json,re,hashlib
p=Path(__file__).resolve().parent
def read(n):return json.loads((p/n).read_text())
tests=(p/'tests.log').read_text();count=int(re.search(r'^# tests (\d+)$',tests,re.M)[1]);assert re.search(r'^# fail 0$',tests,re.M)
jsc=read('policy-jsc-results.json');cold=read('native-first-load-results.json');filled=read('native-filled-first-load-results.json');churn=read('native-churn-results.json');pressure=read('native-pressure-results.json');static=read('policy-native-churn-results.json')
runtime={str(f.relative_to(p/'runtime')):hashlib.sha256(f.read_bytes()).hexdigest() for f in sorted((p/'runtime').rglob('*')) if f.is_file()}
baseline=Path('/var/folders/nd/7mjnltf526q8zsj7g6h92frh0000gn/T/verselyrics-300-smqbxnex/300')
baseline_runtime={str(f.relative_to(baseline/'runtime')):hashlib.sha256(f.read_bytes()).hexdigest() for f in sorted((baseline/'runtime').rglob('*')) if f.is_file()}
assert len(runtime)==15
for run in jsc['runs']:
 assert run['runtimeSHA256']==(baseline_runtime if run['version']=='baseline' else runtime)['Loon/script/SpotifyLyrics.js' if not run['scenario'].startswith(('entry-','wire-')) else 'Loon/script/SpotifyLyrics.Entry.js']
for name in ['native-cold-final.log','native-filled-final.log','native-churn-final.log','native-pressure-final.log','policy-native-churn.log']:assert 'Error' not in (p/name).read_text()
def percent(a,b):return 100*(a/b-1)
def ranges(rows,key):
 v=[percent(r['candidate'][key],r['baseline'][key]) for r in rows];return [round(min(v),3),round(max(v),3)]
same_cold=[r for r in jsc['comparisons'] if r['mode']=='cold' and not r['intentionalBehaviorChange']]
same_seq=[r for r in jsc['comparisons'] if r['mode']=='sequence' and not r['intentionalBehaviorChange']]
policy=[r for r in jsc['comparisons'] if r['intentionalBehaviorChange']]
summary={'version':'3.1.0','adapter':14,'baselineVersion':'3.0.0','baselineRuntimeCommit':'f782e75afe834be7c796f3ce1ec8d2e7939e312a','tests':{'passed':count,'failed':0},'runtimeFiles':15,'jsc':{'processes':len(jsc['runs']),'comparisons':len(jsc['comparisons']),'unchangedColdPeakPercent':ranges(same_cold,'sampledPeakFootprint'),'unchangedColdTimePercent':ranges(same_cold,'milliseconds'),'unchangedSequencePeakPercent':ranges(same_seq,'sampledPeakFootprint'),'unchangedSequenceTimePercent':ranges(same_seq,'milliseconds'),'intentionalBehaviorChanges':policy},'nativeCold':{'processes':len(cold['runs']),'peakPercent':ranges(cold['comparisons'],'sampledMaxHeapBytes'),'timePercent':ranges(cold['comparisons'],'medianMs')},'nativeFilled':{'processes':len(filled['runs']),'peakPercent':ranges(filled['comparisons'],'sampledMaxHeapBytes'),'timePercent':ranges(filled['comparisons'],'medianMs')},'existingChurn':{'processes':len(churn['results']),'songsPerProcess':240,'httpPerProcess':720,'maxActiveHTTP':max(r['maxActiveHTTP'] for r in churn['results'])},'newStaticChurn':{'processes':len(static['results']),'songsPerProcess':120,'responsesPerProcess':240,'httpPerProcess':240,'maxActiveHTTP':max(r['maxActiveHTTP'] for r in static['results']),'pendingAfterCompletion':max(r['activeHTTP'] for r in static['results']),'maxStandardCacheCharacters':max(r['maxCacheCharacters'] for r in static['results'] if r['mode']=='standard'),'maxCompactCacheCharacters':max(r['maxCacheCharacters'] for r in static['results'] if r['mode']=='compact')},'pressure':pressure['comparisons'],'candidateRuntimeSHA256':runtime,'baselineRuntimeSHA256':baseline_runtime,'deviceAcceptance':{'iPhoneLoon':False,'vpnStability':False,'liveCatalogCoverage':False},'scope':'Synthetic local tests and macOS JSC/Node native API mocks. Timed enrichment is additional work versus old static passthrough and can use more memory/time. No universal memory reduction, native cancellation, source completeness or VPN guarantee.'}
(p/'validation-summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n');(p/'bench-runtime-sha256.json').write_text(json.dumps(runtime,indent=2)+'\n')
lines=['# VerseLyrics 3.1.0 measurements','',f'Current validation: **{count} tests passed, zero failed**; native Egern YAML validation passed. Baseline is unchanged 3.0.0 at runtime commit f782e75afe834be7c796f3ce1ec8d2e7939e312a. Native API/compiler test inputs are synthetic; there is no iPhone/VPN acceptance in this report.','', '## Existing behavior comparisons','', '| Experiment | Median sampled peak change | Median elapsed change |','| --- | --- | --- |']
def fmt(x):return f'{x[0]:+.3f}% to {x[1]:+.3f}%'
for name,a,b in [('macOS JSC cold, 12 unchanged cases',ranges(same_cold,'sampledPeakFootprint'),ranges(same_cold,'milliseconds')),('macOS JSC 32 fresh contexts, 2 unchanged cases',ranges(same_seq,'sampledPeakFootprint'),ranges(same_seq,'milliseconds')),('Node cold first load, 10 cases / 240 processes',summary['nativeCold']['peakPercent'],summary['nativeCold']['timePercent']),('Node filled cache first load, 10 cases / 240 processes',summary['nativeFilled']['peakPercent'],summary['nativeFilled']['timePercent'])]:lines.append(f'| {name} | {fmt(a)} | {fmt(b)} |')
lines+=['','The unchanged cases require matching output fingerprints and request counts. These results contain both increases and decreases; this release is not described as uniformly faster or lower-memory. The JSC cold NetEase partial-translation case is a timing outlier (+48.495% in this run); its 32-context sequence is +0.743% and sampled peak is lower. The cold absolute medians are recorded in the raw report, and no on-device cause is inferred.','', '## New behavior comparisons','', '| Case | HTTP per response: 3.0.0 → 3.1.0 | Cold sampled peak change | 32-context sampled peak change |','| --- | --- | --- | --- |']
for variant,label in [('chinese-conversion','Chinese conversion'),('static-cold','Static official → fetched timed'),('static-cached','Static official → cached timed')]:
 for form in ['json','protobuf']:
  a=next(r for r in policy if r['scenario']==f'policy-{variant}-{form}' and r['mode']=='cold');b=next(r for r in policy if r['scenario']==a['scenario'] and r['mode']=='sequence')
  lines.append(f"| {label}, {form} | {a['baseline']['calls']} → {a['candidate']['calls']} | {percent(a['candidate']['sampledPeakFootprint'],a['baseline']['sampledPeakFootprint']):+.3f}% | {percent(b['candidate']['sampledPeakFootprint'],b['baseline']['sampledPeakFootprint']):+.3f}% |")
lines+=['','Chinese preservation eliminates the synthetic conversion request. Static-to-timed results deliberately differ in provider/timing from the old static passthrough and require additional parsing/encoding or source requests. Cold static enrichment uses about 6.3–6.8% more sampled JSC footprint than translating the static original in this fixture; cached upgrade sequences also rise. This is the cost of supplying real timestamps rather than leaving the static text unchanged. Existing work caps, advisory admission and sequential HTTP remain; these measurements cannot establish an iOS memory ceiling.','', '## Switching and pressure','', '- Existing missing-lyrics churn: five candidate clients × JSON/protobuf, 240 different synthetic song IDs, 720 HTTP calls per process, matching output fingerprints. Maximum active HTTP is one; cache remains within 64,000 characters.','- New static-upgrade churn: five clients × two formats × two cache modes = 20 separate processes. Each processes 120 song IDs and 240 lyric responses including immediate cached reopen. Each makes 240 source calls total, zero calls on reopen, maximum active HTTP one, and no HTTP left after completion. Standard cache stayed at or below '+str(summary['newStaticChurn']['maxStandardCacheCharacters'])+' characters; compact stayed at or below '+str(summary['newStaticChurn']['maxCompactCacheCharacters'])+'.','- Pressure mocks retain the established two-maximum unfinished script invocations and one active HTTP request under 60 arrivals at two-millisecond spacing and delayed callbacks. No admission timers; a later client retry can translate after the busy owner drains. Busy responses can omit uncached enrichment.','- Node uses 32 MiB old-space processes and explicit GC in churn experiments. That is a harness configuration, not a Loon RAM limit. Egern completes by awaited return; its harness completion count is not a native $done call.','', '## Reproduce','', 'Pin the 3.0.0 baseline runtime/source above in a separate BASELINE directory. Use a current Node, Python 3 and the public macOS JavaScriptCore framework. The compiler uses an installed Command Line Tools SDK, with no Xcode license changes.','', '```sh','node jsc-fixtures.mjs','node jsc-cache-fixtures.mjs','node jsc-release-fixtures.mjs','node jsc-300-fixtures.mjs','node jsc-policy-fixtures.mjs','clang -isysroot /Library/Developer/CommandLineTools/SDKs/MacOSX.sdk -O2 -framework JavaScriptCore jsc-memory-runner.c -o jsc-memory-runner','python3 policy-bench.py "$BASELINE"','node native-first-load-bench.mjs "$BASELINE"','node native-first-load-bench.mjs "$BASELINE" --populated','node native-playlist-bench.mjs "$BASELINE" --churn','node native-pressure-bench.mjs "$BASELINE"','node policy-playlist-bench.mjs','```','', 'The JSC matrix has 18 cold cases and eight 32-context cases, six alternating trials per version, 312 processes total. Existing-case fingerprints must agree. New policy cases have explicit expected request-count differences. Raw trials are in policy-jsc-results.json, native-first-load-results.json, native-filled-first-load-results.json, native-churn-results.json, native-pressure-results.json and policy-native-churn-results.json. Runtime hashes are in bench-runtime-sha256.json and validation-summary.json.','']
(p/'MEASUREMENTS.md').write_text('\n'.join(lines));print(json.dumps({k:summary[k] for k in ['version','tests','runtimeFiles','nativeCold','nativeFilled','newStaticChurn']}))
